INSERT INTO temporary_questions (essence_fk, text, points, options) VALUES
('00000000-0000-0000-0000-000000000000', 'Ist die UI in Softwareprojekten nur für die Optik wichtig?', 2, '[{"text": "Nein", "correct": true, "because": "Usability und Akzeptanz zählen mehr"}, {"text": "Ja", "correct": false, "because": "Funktionalität wird ignoriert"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches Ziel verfolge ich mit einer guten UI in meinem Projekt?', 3, '[{"text": "Nutzerfreundlichkeit erhöhen", "correct": true, "because": "Fördert intuitive Bedienung"}, {"text": "Codegröße minimieren", "correct": false, "because": "Nicht UI-Fokus"}, {"text": "Datenrate steigern", "correct": false, "because": "Backend-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte machen eine UI für Softwareprojekte entscheidend?', 5, '[{"text": "Usability", "correct": true, "because": "Erleichtert Bedienung"}, {"text": "Akzeptanz", "correct": true, "because": "Nutzer überzeugt"}, {"text": "Hohe Auflösung", "correct": false, "because": "Technisch, nicht UI-Kern"}, {"text": "Schnelle Ladezeit", "correct": false, "because": "Performance, nicht UI"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) Eine schlechte UI kann Nutzer abschrecken. b) UI hat keinen Einfluss auf den Erfolg.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "UI beeinflusst Erfolg direkt"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ignoriere ich bei der Rolle der UI in meinem Projekt?', 4, '[{"text": "Nutzerfeedback", "correct": false, "because": "Entscheidend für Anpassung"}, {"text": "Interaktionsdesign", "correct": false, "because": "Kern der Usability"}, {"text": "Farbanimationen", "correct": true, "because": "Sekundär gegenüber Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine gute UI auch die Lernkurve verkürzt?', 2, '[{"text": "Ja", "correct": true, "because": "Intuitive Bedienung hilft"}, {"text": "Nein", "correct": false, "because": "Lernaufwand sinkt"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen Faktor priorisiere ich bei der UI für ein Softwareprojekt?', 3, '[{"text": "Konsistenz", "correct": true, "because": "Fördert Vertrautheit"}, {"text": "Hohe Farbtiefe", "correct": false, "because": "Optisch, nicht funktional"}, {"text": "Maximale Pixelzahl", "correct": false, "because": "Technisch, nicht UI-Kern"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Rollen spielt die UI in Softwareprojekten?', 5, '[{"text": "Erster Eindruck", "correct": true, "because": "Beeinflusst Akzeptanz"}, {"text": "Effizienzsteigerung", "correct": true, "because": "Vereinfacht Bedienung"}, {"text": "Datenkompression", "correct": false, "because": "Backend-Thema"}, {"text": "Netzwerkgeschwindigkeit", "correct": false, "because": "Nicht UI-relevant"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört: a) Eine gute UI erhöht die Nutzerzufriedenheit. b) Sie ist nur für unerfahrene Nutzer wichtig. Stimmt das?', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Alle Nutzer profitieren"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Was brauche ich nicht für die Rolle der UI in einem Projekt?', 4, '[{"text": "Benutzerführung", "correct": false, "because": "Kern der Usability"}, {"text": "Reaktionsfähigkeit", "correct": false, "because": "Fördert Nutzererlebnis"}, {"text": "3D-Effekte", "correct": true, "because": "Nice-to-have, nicht essenziell"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Ist die UI nur für die Optik da?', 2, '[{"text": "Nein", "correct": true, "because": "Funktionalität entscheidend"}, {"text": "Ja", "correct": false, "because": "Usability übersehen"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche Aspekte der UI fördern die Akzeptanz?', 4, '[{"text": "Intuitive Navigation", "correct": true, "because": "Erleichtert Nutzung"}, {"text": "Visuelles Feedback", "correct": true, "because": "Zeigt Interaktionen"}, {"text": "Hohe Serverlast", "correct": false, "because": "Backend-Thema"}]'),
('00000000-0000-0000-0000-000000000000', 'Habe gehört, dass eine schlechte UI den Projektflop garantiert. Stimmt das?', 2, '[{"text": "Nein", "correct": true, "because": "Kann kompensiert werden, aber riskant"}, {"text": "Ja", "correct": false, "because": "Nicht zwangsläufig entscheidend"}]'),
('00000000-0000-0000-0000-000000000000', 'Welchen UI-Aspekt priorisiere ich für ein produktives Team?', 3, '[{"text": "Effizientes Layout", "correct": true, "because": "Spart Zeit bei Nutzung"}, {"text": "Farbvielfalt", "correct": false, "because": "Sekundär"}, {"text": "Animierte Übergänge", "correct": false, "because": "Ablenkend möglich"}]'),
('00000000-0000-0000-0000-000000000000', 'Sind diese Aussagen korrekt? a) UI beeinflusst die Fehlerquote. b) Usability ist nur für Endnutzer wichtig.', 3, '[{"text": "Nur a) stimmt", "correct": true, "because": "Usability auch für Entwickler"}, {"text": "Beides stimmt", "correct": false, "because": "b) ist falsch"}, {"text": "Nur b) stimmt", "correct": false, "because": "a) ist korrekt"}, {"text": "Beides falsch", "correct": false, "because": "a) ist richtig"}]'),
('00000000-0000-0000-0000-000000000000', 'Welche UI-Elemente steigern die Produktivität?', 5, '[{"text": "Klare Schaltflächen", "correct": true, "because": "Schnelle Interaktion"}, {"text": "Tastenkürzel", "correct": true, "because": "Beschleunigen Bedienung"}, {"text": "Hohe Pixeldichte", "correct": false, "because": "Technisch, nicht UI-Kern"}, {"text": "Blinkende Icons", "correct": false, "because": "Ablenkend"}]'),
('00000000-0000-0000-0000-000000000000', 'Was ist bei der Rolle der UI unwichtig?', 3, '[{"text": "Reaktionszeit", "correct": false, "because": "Fördert Nutzererlebnis"}, {"text": "Benutzerführung", "correct": false, "because": "Kern der Usability"}, {"text": "Exotische Schriftarten", "correct": true, "because": "Sekundär gegenüber Funktion"}]'),
('00000000-0000-0000-0000-000000000000', 'Wie war das nochmal? Kann eine UI den Projektwert steigern?', 3, '[{"text": "Ja", "correct": true, "because": "Bessere Akzeptanz erhöht Nutzen"}, {"text": "Nein", "correct": false, "because": "Wert oft unterschätzt"}]'),
('00000000-0000-0000-0000-000000000000', 'Kannst du dich erinnern, ob eine gute UI auch Supportkosten senkt?', 2, '[{"text": "Ja", "correct": true, "because": "Weniger Nutzerfragen"}, {"text": "Nein", "correct": false, "because": "Intuitivität hilft"}]'),
('00000000-0000-0000-0000-000000000000', 'Welches UI-Feature wähle ich für ein neues Softwareprojekt?', 4, '[{"text": "Responsive Design", "correct": true, "because": "Passt sich Geräten an"}, {"text": "Hohe Farbsättigung", "correct": false, "because": "Optisch, nicht funktional"}, {"text": "Große Bildschirmgröße", "correct": false, "because": "Hardwareabhängig"}]');
